module paint_the_numbers(\n    input clk, rst_n, start,\n    input [6:0] n, \n    input [7:0] arr_0, arr_1, arr_2, arr_3,\n    input [7:0] arr_4, arr_5, arr_6, arr_7,\n    input [7:0] arr_8, arr_9, arr_10, arr_11,\n    input [7:0] arr_12, arr_13, arr_14, arr_15,\n    output reg [7:0] color_count,\n    output reg done\n);\n\n    // State encoding\n    localparam [3:0] \n        IDLE          = 4'd0, \n        INIT          = 4'd1, \n        FIND_MIN      = 4'd2, \n        FIND_MIN_LOOP = 4'd3,\n        FOUND_MIN     = 4'd4, \n        SET_COLOR     = 4'd5, \n        MARK_LOOP     = 4'd6, \n        DONE_STATE    = 4'd7;\n\n    reg [3:0] state, next_state;\n    reg [15:0] colored;  // Bitmask for colored elements\n    reg [3:0] k, j;      // Loop counters\n    reg [7:0] temp_min;\n    reg [3:0] temp_index;\n    reg [7:0] current_min;\n\n    wire [7:0] arr_k = (k == 4'd0)  ? arr_0  : \n                      (k == 4'd1)  ? arr_1  : \n                      (k == 4'd2)  ? arr_2  : \n                      (k == 4'd3)  ? arr_3  : \n                      (k == 4'd4)  ? arr_4  : \n                      (k == 4'd5)  ? arr_5  : \n                      (k == 4'd6)  ? arr_6  : \n                      (k == 4'd7)  ? arr_7  : \n                      (k == 4'd8)  ? arr_8  : \n                      (k == 4'd9)  ? arr_9  : \n                      (k == 4'd10) ? arr_10 : \n                      (k == 4'd11) ? arr_11 : \n                      (k == 4'd12) ? arr_12 : \n                      (k == 4'd13) ? arr_13 : \n                      (k == 4'd14) ? arr_14 : arr_15;\n\n    wire [7:0] arr_j = (j == 4'd0)  ? arr_0  : \n                      (j == 4'd1)  ? arr_1  : \n                      (j == 4'd2)  ? arr_2  : \n                      (j == 4'd3)  ? arr_3  : \n                      (j == 4'd4)  ? arr_4  : \n                      (j == 4'd5)  ? arr_5  : \n                      (j == 4'd6)  ? arr_6  : \n                      (j == 4'd7)  ? arr_7  : \n                      (j == 4'd8)  ? arr_8  : \n                      (j == 4'd9)  ? arr_9  : \n                      (j == 4'd10) ? arr_10 : \n                      (j == 4'd11) ? arr_11 : \n                      (j == 4'd12) ? arr_12 : \n                      (j == 4'd13) ? arr_13 : \n                      (j == 4'd14) ? arr_14 : arr_15;\n\n    wire [7:0] remainder = (current_min != 8'd0) ? (arr_j % current_min) : 8'd0;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            color_count <= 8'd0;\n            done <= 1'b0;\n            colored <= 16'd0;\n            k <= 4'd0;\n            j <= 4'd0;\n            temp_min <= 8'd255;\n            temp_index <= 4'd0;\n            current_min <= 8'd0;\n        end else begin\n            state <= next_state;\n\n            case (state)\n                INIT: begin\n                    colored <= 16'd0;\n                    color_count <= 8'd0;\n                    temp_min <= 8'd255;\n                    done <= 1'b0;\n                end\n\n                FIND_MIN: begin\n                    k <= 4'd0;\n                    temp_min <= 8'd255;\n                end\n\n                FIND_MIN_LOOP: begin\n                    if (k < n) begin\n                        if (!colored[k]) begin\n                            if (arr_k < temp_min) begin\n                                temp_min <= arr_k;\n                                temp_index <= k;\n                            end\n                        end\n                        k <= k + 4'd1;\n                    end\n                end\n\n                FOUND_MIN: begin\n                    current_min <= temp_min;\n                end\n\n                SET_COLOR: begin\n                    colored[temp_index] <= 1'b1;\n                    j <= 4'd0;\n                    color_count <= color_count + 8'd1;\n                end\n\n                MARK_LOOP: begin\n                    if (j < n) begin\n                        if (!colored[j] && (remainder == 8'd0)) begin\n                            colored[j] <= 1'b1;\n                        end\n                        j <= j + 4'd1;\n                    end\n                end\n\n                DONE_STATE: begin\n                    done <= 1'b1;\n                end\n            endcase\n        end\n    end\n\n    always @(*) begin\n        case (state)\n            IDLE:          next_state = start ? INIT : IDLE;\n            INIT:          next_state = FIND_MIN;\n            FIND_MIN:      next_state = FIND_MIN_LOOP;\n            FIND_MIN_LOOP: next_state = (k >= n) ? FOUND_MIN : FIND_MIN_LOOP;\n            FOUND_MIN:     next_state = (temp_min == 8'd255) ? DONE_STATE : SET_COLOR;\n            SET_COLOR:     next_state = MARK_LOOP;\n            MARK_LOOP:     next_state = (j >= n) ? FIND_MIN : MARK_LOOP;\n            DONE_STATE:    next_state = DONE_STATE;\n            default:       next_state = IDLE;\n        endcase\n    end\n\nendmodule